    #[serde(default)]
    pub issue: Option<String>,
    /// `delivery` or `decision`.
    #[serde(default = "default_profile")]
    pub profile: String,
    /// `basic`, `standard` or `high`.
    #[serde(default = "default_assurance")]
    pub assurance: String,
    /// Interview answers by question id.
    #[serde(default)]
